INSERT INTO destinations(destination_name,country,description,image) VALUES
('Bali','Indonesia','Temples, rice terraces and island life.','https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=900&q=80'),('Kathmandu','Nepal','Himalayan culture and mountain trails.','https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=900&q=80'),('Kyoto','Japan','Historic lanes, gardens and cuisine.','https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=900&q=80'),('Marrakech','Morocco','Colorful souks and desert gateways.',''),('Lisbon','Portugal','Coastal charm and old-world neighborhoods.',''),('Cusco','Peru','Andean heritage and Inca trails.',''),('Reykjavik','Iceland','Northern lights and volcanic landscapes.',''),('Cape Town','South Africa','Mountain views and vibrant coastlines.','');
INSERT INTO packages(destination_id,package_name,description,duration,price,image) VALUES
(1,'Bali: Island Slowdown','Find balance between temple visits, beach time and local food.','7 days / 6 nights',1890,'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1000&q=80'),(1,'Bali Beyond the Beach','Explore Ubud, waterfalls and quiet coastal villages.','9 days / 8 nights',2390,''),(2,'Nepal: Himalayan Trails','Walk mountain foothills with local guides and welcoming teahouses.','10 days / 9 nights',2790,'https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=1000&q=80'),(2,'Kathmandu to Pokhara','A culture-rich journey from city temples to lakeside views.','8 days / 7 nights',2190,''),(3,'Japan: Kyoto & Beyond','Discover Kyoto traditions, food markets and the countryside.','8 days / 7 nights',3290,'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1000&q=80'),(3,'Japan in a Week','A first-timer route through Tokyo, Kyoto and Osaka.','7 days / 6 nights',2990,''),(4,'Morocco: Souks to Sahara','Follow the colors of Marrakech into the desert dunes.','9 days / 8 nights',2490,''),(4,'Morocco: Atlas & Medina','Mountain villages, historic medinas and shared meals.','7 days / 6 nights',1990,''),(5,'Portugal: Lisbon & Coast','Savor Lisbon and unwind in Atlantic coastal towns.','7 days / 6 nights',2090,''),(5,'Portugal by Rail','Travel between Lisbon, Porto and the Douro Valley.','8 days / 7 nights',2390,''),(6,'Peru: Sacred Valley','Explore Cusco and Inca heritage at a thoughtful pace.','9 days / 8 nights',3190,''),(7,'Iceland: Fire & Ice','Chase waterfalls, geothermal pools and northern skies.','6 days / 5 nights',2890,''),(8,'Cape Town & Winelands','Coastal scenery, city culture and vineyard visits.','7 days / 6 nights',2690,'');
