CREATE DATABASE IF NOT EXISTS tour_travel_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tour_travel_db;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40) DEFAULT '',password VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',status TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE destinations(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,destination_name VARCHAR(120) NOT NULL,country VARCHAR(120) NOT NULL,description TEXT,image VARCHAR(500),status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE packages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,destination_id INT UNSIGNED NOT NULL,package_name VARCHAR(180) NOT NULL,description TEXT NOT NULL,duration VARCHAR(60) NOT NULL,itinerary TEXT,accommodation TEXT,transportation TEXT,price DECIMAL(10,2) NOT NULL,image VARCHAR(500),status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(destination_id),CONSTRAINT fk_package_destination FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE bookings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,package_id INT UNSIGNED NOT NULL,travel_date DATE NOT NULL,travellers TINYINT UNSIGNED NOT NULL,total_amount DECIMAL(10,2) NOT NULL,special_requirements TEXT,booking_status ENUM('pending','approved','rejected','completed') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),INDEX(package_id),INDEX(booking_status),CONSTRAINT fk_booking_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_booking_package FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE contact_messages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,subject VARCHAR(200) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB;
UPDATE packages SET itinerary=CASE destination_id WHEN 1 THEN 'Day 1: Arrive and settle in. Days 2–3: Ubud temples, rice terraces and a guided village visit. Days 4–5: Waterfalls and coastal time. Final day: Farewell breakfast and departure.' WHEN 2 THEN 'Day 1: Arrive in Kathmandu. Days 2–3: Explore heritage squares and local markets. Days 4–6: Guided foothill walks with village stays. Final day: Return and depart.' WHEN 3 THEN 'Day 1: Arrive in Japan. Days 2–4: Kyoto shrines, gardens and neighborhood food walks. Days 5–6: Countryside excursion and free time. Final day: Departure.' ELSE 'Arrival and orientation, guided local highlights, time to explore independently, and a final-day departure.' END,accommodation='Handpicked locally owned guesthouses and comfortable boutique stays, subject to availability.',transportation='Airport arrival guidance and ground transfers during scheduled group activities are included.';
